def parse_roman(s):
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    previous = 0
    for ch in reversed(s):
        if ch not in values:
            raise ValueError('invalid symbol')
        current = values[ch]
        if current <= previous:
            total = total - current
        else:
            total = total + current
        previous = current
    return total
```

