    total = 0
    for i, ch in enumerate(reversed(s)):
        if ch not in values:
            raise ValueError('invalid symbol')
        current = values[ch]
        if i > 0 and current > values[s[i - 1]]:
            total += current - 2 * values[s[i - 1]]
        else:
            total += current
